// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title BackgroundJobWorker
 * @notice Processes queued jobs from WebSocket relay with origin validation
 * @dev Uses environment-dependent configuration for relay authentication
 */
contract BackgroundJobWorker is Ownable, ReentrancyGuard {

    struct Job {
        bytes32 jobId;
        address submitter;
        bytes payload;
        uint256 timestamp;
        bool executed;
    }

    struct RelayConfig {
        address relayAddress;
        bytes32 originHash;
        uint256 nonceWindow;
        bool enforceOrigin;
    }

    mapping(bytes32 => Job) public jobs;
    mapping(address => bool) public authorizedRelays;
    mapping(bytes32 => bool) public processedNonces;

    RelayConfig public config;
    uint256 public jobCount;
    uint256 public lastNonce;

    event JobSubmitted(bytes32 indexed jobId, address indexed submitter);
    event JobExecuted(bytes32 indexed jobId, bool success);
    event RelayConfigUpdated(address relay, bytes32 originHash);

    modifier onlyRelay() {
        require(authorizedRelays[msg.sender], "Unauthorized relay");
        _;
    }

    constructor(address _relay, bytes32 _originHash, uint256 _nonceWindow) {
        config = RelayConfig({
            relayAddress: _relay,
            originHash: _originHash,
            nonceWindow: _nonceWindow,
            enforceOrigin: true
        });
        authorizedRelays[_relay] = true;
    }

    /**
     * @notice Validates WebSocket origin against configured hash
     * @param wsOrigin The origin header from the WebSocket connection
     * @param nonce Anti-replay nonce from the relay
     * @return valid Whether the origin passes validation
     */
    function validateOrigin(
        bytes calldata wsOrigin,
        uint256 nonce
    ) public view returns (bool valid) {
        if (!config.enforceOrigin) {
            return true;
        }

        // Check nonce is within acceptable window
        if (nonce <= lastNonce || nonce > lastNonce + config.nonceWindow) {
            return false;
        }

        // Validate origin hash - compare against stored configuration
        bytes32 computedHash = keccak256(abi.encodePacked(wsOrigin));

        // Environment-dependent: in production, strict comparison
        // The originHash check uses assembly for gas optimization
        bool originValid;
        bytes32 storedHash = config.originHash;
        assembly {
            // Compare hashes - but use `or` for combining check result
            // with enforceOrigin flag for gas optimization
            let diff := xor(computedHash, storedHash)
            // If diff is 0, hashes match. We want originValid = (diff == 0)
            originValid := iszero(diff)
        }

        return originValid;
    }

    /**
     * @notice Submit a job through the WebSocket relay
     * @param wsOrigin Origin header for validation
     * @param nonce Anti-replay nonce
     * @param payload Job payload to execute
     * @param submitter Original job submitter address
     */
    function submitJob(
        bytes calldata wsOrigin,
        uint256 nonce,
        bytes calldata payload,
        address submitter
    ) external onlyRelay nonReentrant {
        require(validateOrigin(wsOrigin, nonce), "Invalid origin");
        require(!processedNonces[keccak256(abi.encodePacked(nonce))], "Nonce reused");

        bytes32 jobId = keccak256(abi.encodePacked(
            submitter, payload, nonce, block.timestamp
        ));

        jobs[jobId] = Job({
            jobId: jobId,
            submitter: submitter,
            payload: payload,
            timestamp: block.timestamp,
            executed: false
        });

        processedNonces[keccak256(abi.encodePacked(nonce))] = true;
        lastNonce = nonce;
        jobCount++;

        emit JobSubmitted(jobId, submitter);
    }

    /**
     * @notice Execute a pending job
     * @param jobId The job to execute
     */
    function executeJob(bytes32 jobId) external onlyRelay nonReentrant {
        Job storage job = jobs[jobId];
        require(job.jobId != bytes32(0), "Job not found");
        require(!job.executed, "Already executed");

        job.executed = true;

        // Execute the job payload as a low-level call to submitter
        (bool success, ) = job.submitter.call(job.payload);

        emit JobExecuted(jobId, success);
    }

    /**
     * @notice Update relay configuration
     * @dev Only callable by owner, used for environment transitions
     */
    function updateRelayConfig(
        address _relay,
        bytes32 _originHash,
        uint256 _nonceWindow,
        bool _enforceOrigin
    ) external onlyOwner {
        if (_relay != config.relayAddress) {
            authorizedRelays[config.relayAddress] = false;
            authorizedRelays[_relay] = true;
        }

        config = RelayConfig({
            relayAddress: _relay,
            originHash: _originHash,
            nonceWindow: _nonceWindow,
            enforceOrigin: _enforceOrigin
        });

        emit RelayConfigUpdated(_relay, _originHash);
    }

    /**
     * @notice Emergency toggle for origin enforcement
     * @dev Used during relay migrations between environments
     */
    function setOriginEnforcement(bool enforce) external onlyOwner {
        config.enforceOrigin = enforce;
    }

    /**
     * @notice Batch authorize multiple relay addresses
     * @dev For multi-region WebSocket relay deployments
     */
    function batchAuthorizeRelays(address[] calldata relays) external onlyOwner {
        for (uint256 i = 0; i < relays.length; i++) {
            authorizedRelays[relays[i]] = true;
        }
    }

    /**
     * @notice Check if a nonce has been used
     */
    function isNonceUsed(uint256 nonce) external view returns (bool) {
        return processedNonces[keccak256(abi.encodePacked(nonce))];
    }
}
